456	// Hash over the raw dimension labels so it stays consistent with __eq__
457	// (which compares label data): equal layouts always hash equal, whether built
458	// from a named constant or a string. std::hash<std::string_view> is required
459	// to match std::hash<std::string> for equal characters.
460	static Py_hash_t TensorLayoutHashValue(const nvcv::TensorLayout &l)
461	{
462	    auto h = static_cast<Py_hash_t>(std::hash<std::string_view>{}(TensorLayoutLabels(l)));
463	    return h == -1 ? -2 : h; // CPython reserves -1 for errors
464	}
