466	// Installed directly as tp_hash: dict/set operations then skip the Python
467	// method-dispatch of a def("__hash__"), which costs several times the hash
468	// itself on this hot path.
469	static Py_hash_t TensorLayoutTpHash(PyObject *self)
470	{
471	    try
472	    {
473	        return TensorLayoutHashValue(py::cast<nvcv::TensorLayout &>(py::handle(self)));
474	    }
475	    catch (const std::exception &e) // NOSONAR: tp_hash is a C slot; no C++ exception may reach CPython
476	    {
477	        PyErr_SetString(PyExc_TypeError, e.what());
478	        return -1;
479	    }
