482	void ExportTensorLayout(py::module &m)
483	{
484	    auto cls = py::class_<nvcv::TensorLayout>(m, "TensorLayout");
485	    cls.def(py::init<const char *>())
486	        .def(
487	            "__eq__", [](const nvcv::TensorLayout &a, const nvcv::TensorLayout &b) { return a == b; },
488	            py::is_operator(), "Check if two TensorLayout objects are equal.")
489	        .def(
490	            "__ne__", [](const nvcv::TensorLayout &a, const nvcv::TensorLayout &b) { return a != b; },
491	            py::is_operator(), "Check if two TensorLayout objects are not equal.")
492	        // Kept alongside the tp_hash slot so TensorLayout.__hash__ resolves to
493	        // the same value; without a def, pybind11 nulls __hash__ once __eq__
494	        // is defined, leaving TensorLayout unhashable.
495	        .def(
496	            "__hash__", [](const nvcv::TensorLayout &l) { return TensorLayoutHashValue(l); },
497	            "Return a value-based hash so TensorLayout can be used as a dict key or set member.")
498	        .def("__repr__", &TensorLayoutToString, "Return the string representation of the TensorLayout object.");
499	
500	    // The class constants are the interned instances themselves (not
501	    // per-access getters), so `TensorLayout.NHWC is tensor.layout` holds.
502	    auto intern = [&cls](const char *name, const nvcv::TensorLayout &layout)
503	    {
504	        py::object obj = py::cast(layout);
505	        InternedTensorLayouts().try_emplace(std::string(TensorLayoutLabels(layout)), obj);
506	        cls.attr(name) = obj;
507	    };
508	    cls.attr("NONE") = py::cast(nvcv::TENSOR_NONE);
509	#define NVCV_DETAIL_DEF_TLAYOUT(LAYOUT) intern(#LAYOUT, nvcv::TENSOR_##LAYOUT);
510	#include <nvcv/TensorLayoutDef.inc> // NOSONAR: this include expands TensorLayout constants inside the binding chain.
511	#undef NVCV_DETAIL_DEF_TLAYOUT
512	
513	    // Override last: pybind's def("__hash__") above set tp_hash to CPython's
514	    // slot dispatcher; replace it with the direct C implementation.
515	    auto *tp    = reinterpret_cast<PyTypeObject *>(cls.ptr());
516	    tp->tp_hash = &TensorLayoutTpHash;
517	    PyType_Modified(tp);
518	
519	    py::implicitly_convertible<py::str, nvcv::TensorLayout>();
520	}
